#!/usr/bin/env python3
"""
Guarded patch: swap in new user-generated background images for Mining
and Woodcutting. Image-only change - no Kotlin code changes needed,
same drawable filenames as before.
"""
import os
import base64

REPO_ROOT = "."
MINING_PATH = os.path.join(REPO_ROOT, "app/src/main/res/drawable/bg_mining_pickaxes.webp")
WOODCUTTING_PATH = os.path.join(REPO_ROOT, "app/src/main/res/drawable/bg_woodcutting_pattern.webp")

MINING_B64 = """"""
WOODCUTTING_B64 = """"""


def write_image(path, b64):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    data = base64.b64decode(b64)
    if os.path.exists(path) and os.path.getsize(path) == len(data):
        print(f"SKIP (already present, same size): {path}")
        return
    with open(path, "wb") as f:
        f.write(data)
    print(f"WROTE: {path} ({len(data)} bytes)")


write_image(MINING_PATH, MINING_B64)
write_image(WOODCUTTING_PATH, WOODCUTTING_B64)

print("Done.")
